from collections import deque
def shapes(g):
    Hl,Wl=len(g),len(g[0]); seen=[[0]*Wl for _ in range(Hl)]; out=[]
    for i in range(Hl):
        for j in range(Wl):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=1; cs=[]
                while q:
                    r,c=q.popleft(); cs.append((r,c))
                    for dr2,dc2 in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr2,c+dc2
                        if 0<=nr<Hl and 0<=nc<Wl and not seen[nr][nc] and g[nr][nc]==col:
                            seen[nr][nc]=1; q.append((nr,nc))
                rs=[r for r,_ in cs]; cls=[c for _,c in cs]
                # grid-relative pattern
                r0,c0=min(rs),min(cls)
                pat=tuple(sorted((r-r0,c-c0) for r,c in cs))
                out.append(dict(col=col,n=len(cs),bb=(min(rs),min(cls),max(rs),max(cls)),pat=pat))
    return out
